class CinematicUpsCard extends HTMLElement {
constructor(){super();this.attachShadow({mode:"open"});}
setConfig(c){if(!c.battery_entity)throw Error("battery_entity required");this.c=c;this.render();}
set hass(h){this.h=h;this.render();}
getCardSize(){return 6;}
render(){
if(!this.h||!this.c)return;
const c=this.c,h=this.h,s=k=>h.states[c[k]]?.state??"—",num=k=>{const v=s(k);return v==="—"||!Number.isFinite(Number(v))?null:Number(v);};
const esc=v=>String(v??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));
const charge=num("battery_entity"),pct=charge===null?0:Math.max(0,Math.min(100,charge)),status=s("status_entity");
const warn=/\\b(ALARM|RB|FSD|LB)\\b/.test(status)||(charge!==null&&pct<=20),ob=/\\bOB\\b/.test(status);
const color=warn?"#ff5068":ob?"#ffb43d":"#29f9bc";
const runtime=num("runtime_entity"),unit=h.states[c.runtime_entity]?.attributes?.unit_of_measurement;
const seconds=runtime===null?null:runtime*(unit==="min"?60:unit==="h"?3600:1);
const time=seconds===null?"—":Math.floor(seconds/3600)+"ש׳ "+Math.floor(seconds%3600/60)+"ד׳";
const date=c.battery_install_date,valid=date&&/^\\d{4}-\\d{2}-\\d{2}$/.test(date);
const days=valid?Math.max(0,Math.floor((Date.now()-new Date(date+"T00:00:00").getTime())/86400000)):null;
const metric=(label,key,unit)=>'<div class="metric"><span>'+label+'</span><strong>'+esc(s(key))+' <small>'+unit+'</small></strong></div>';
this.shadowRoot.innerHTML='<style>:host{display:block}ha-card{--glow:'+color+';color:#eaffff;background:radial-gradient(ellipse at 50% 15%,#155357,#081b2c 55%,#060c17);border:1px solid #286a77;border-radius:22px;overflow:hidden;box-shadow:0 10px 40px #0006}.body{padding:20px;direction:rtl}.top,.bottom{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap}h2{font-size:19px;margin:0}.status{border:1px solid var(--glow);border-radius:20px;color:var(--glow);padding:5px 10px}.stage{display:flex;justify-content:center;align-items:center;gap:15px;min-height:265px}.battery{height:210px;width:105px;position:relative;filter:drop-shadow(0 0 17px var(--glow))}.cap{position:absolute;top:0;left:28px;width:49px;height:12px;background:#b2eeea;border-radius:8px}.shell{position:absolute;inset:10px 4px 0;border:4px solid #8bdfd8;border-radius:18px 18px 24px 24px;overflow:hidden;transform:perspective(400px) rotateY(-10deg);background:#04121a}.fill{position:absolute;bottom:0;width:100%;height:var(--fill);transition:height 1.2s;background:linear-gradient(90deg,#067b64,var(--glow),#077a64);box-shadow:0 0 25px var(--glow)}.fill:before{content:"";position:absolute;top:-7px;width:100%;height:15px;border-radius:50%;background:#c5fff2}.bubble{position:absolute;bottom:0;left:var(--x);width:5px;height:5px;border-radius:50%;background:#fff;animation:rise 3s linear infinite;animation-delay:var(--delay)}@keyframes rise{to{transform:translateY(-175px);opacity:0}}.percent{font-size:39px;font-weight:800;direction:ltr;text-shadow:0 0 18px var(--glow)}.hint{font-size:12px;color:#b1d7df}.device{width:80px;max-height:130px;object-fit:contain}.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.metric{background:#0a2334;border:1px solid #285c6b;border-radius:12px;padding:12px}.metric span{display:block;color:#a9cbd5;font-size:12px}.metric strong{display:block;font-size:20px;direction:ltr;text-align:right}.metric small{font-size:11px}.bottom{margin-top:14px;color:#a8d1d8;font-size:12px}button{border:1px solid #3b8491;border-radius:9px;background:#113744;color:#fff;padding:8px 12px;cursor:pointer}@media(prefers-reduced-motion:reduce){*,*:before{animation:none!important;transition:none!important}}</style>'+
'<ha-card><div class="body"><div class="top"><h2>'+esc(c.name||"Cinematic UPS")+'</h2><span class="status">'+esc(status)+'</span></div><div class="stage"><div><div class="percent">'+(charge===null?"—":Math.round(pct)+"%")+'</div><div class="hint">זמן גיבוי: '+esc(time)+'</div></div><div class="battery"><div class="cap"></div><div class="shell"><div class="fill" style="--fill:'+pct+'%"><i class="bubble" style="--x:25%;--delay:0s"></i><i class="bubble" style="--x:60%;--delay:1s"></i><i class="bubble" style="--x:45%;--delay:2s"></i></div></div></div>'+(c.image?'<img class="device" src="'+esc(c.image)+'" alt="UPS">':"")+'</div><div class="metrics">'+metric("עומס","load_entity","%")+metric("הספק אמיתי","power_entity","W")+metric("הספק מדומה","apparent_power_entity","VA")+metric("מתח כניסה","voltage_entity","V")+'</div><div class="bottom"><span>'+(days===null?"":"מצברים: "+esc(date)+" · "+days+" ימים")+'</span>'+(c.beeper_entity?'<button id="beeper">זמזם: '+esc(s("beeper_status_entity"))+'</button>':"")+'</div></div></ha-card>';
this.shadowRoot.getElementById("beeper")?.addEventListener("click",()=>this.dispatchEvent(new CustomEvent("hass-more-info",{bubbles:true,composed:true,detail:{entityId:c.beeper_entity}})));
}}
if(!customElements.get("cinematic-ups-card"))customElements.define("cinematic-ups-card",CinematicUpsCard);
window.customCards=window.customCards||[];
window.customCards.push({type:"cinematic-ups-card",name:"Cinematic UPS Card",description:"Animated UPS monitor"});